// Emits (workspace id, client name, api key) from CS PDCA. Keys never leave n8n:
// this payload goes straight into the Postgres node below it.
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const ws = String(j.col_5 ?? '').trim();
  const key = String(j.col_6 ?? '').trim();
  const name = String(j['Customer Success'] ?? '').trim();
  const doc = String(j.col_4 ?? '').trim();
  if (!ws || !key || !name || doc.length < 30) continue;
  if (!/^\d+$/.test(ws)) continue;              // skips the header row
  rows.push({ ws, key, name });
}
return [{ json: { candidates: rows.length, payload: JSON.stringify(rows) } }];
